(function() {
  var map, resize, windIcon;

  resize = function() {
    var newHeight;
    newHeight = $(window).height() - $('nav').height();
    return $('#map').height(newHeight);
  };

  resize();

  $(window).resize(resize);

  map = L.map('map').setView([46.5, 2], 6);

  L.tileLayer('//pioupiou.fr/tiles/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors'
  }).addTo(map);

  windIcon = L.divIcon({
    className: 'map-wind-icon',
    iconSize: [26, 48],
    popupAnchor: [1, -10],
    iconAnchor: [13, 12]
  });

  L.WindMarker = L.Marker.extend({
    options: {
      speed: 0,
      heading: 0,
      title: '',
      icon: windIcon
    },
    _setPos: function(pos) {
      var colorIndex, colorX, rotate;
      L.Marker.prototype._setPos.call(this, pos);
      rotate = 'rotate(' + this.options.heading + 'deg)';
      colorIndex = Math.floor(this.options.speed / 5);
      if (colorIndex > 15) {
        colorIndex = 15;
      }
      colorX = -colorIndex * 26;
      this._icon.style[L.DomUtil.TRANSFORM] += ' ' + rotate;
      this._icon.style[L.DomUtil.TRANSFORM + '-origin'] = '13px 10px';
      this._icon.style['background-position'] = colorX + 'px 0px';
      return this._icon.title = this.options.title;
    }
  });

  L.windMarker = function(pos, options) {
    return new L.WindMarker(pos, options);
  };

  $.getJSON("//api.openwindmap.org/v1/live/all", function(stations) {
    var now, timeout;
    now = (new Date).getTime();
    timeout = 45;
    return stations.data.forEach(function(s) {
      var delay, title;
      delay = Math.round((now - new Date(s.measurements.date).getTime()) / 60000);
      if (delay > timeout) {
        return;
      }
      if (s.location.date === null) {
        return;
      }
      title = s.meta.name + '\n';
      title += 'il y a ' + delay + ' minute(s)\n';
      title += 'min : ' + s.measurements.wind_speed_min + ' km/h\n';
      title += 'MOY : ' + s.measurements.wind_speed_avg + ' km/h\n';
      title += 'max : ' + s.measurements.wind_speed_max + ' km/h\n';
      return L.windMarker([s.location.latitude, s.location.longitude], {
        heading: s.measurements.wind_heading,
        speed: s.measurements.wind_speed_max,
        title: title
      }).addTo(map);
    });
  }).always(function() {
    return $('.map-message.alert-info').hide();
  }).fail(function() {
    return $('.map-message.alert-danger').show();
  });

}).call(this);

